rollback.sql:
DELETE FROM krrg_grades
WHERE code IN ('JUNIOR', 'JUNIOR_PLUS', 'MIDDLE', 'MIDDLE_PLUS',
               'SENIOR', 'STAFF', 'PRINCIPAL', 'LEAD');

changeSet.sql:
-- 1. Перепривязываем ссылки с JUNIOR+ на JUNIOR_PLUS UPDATE krrg_vacancy_grade_link l SET grade_id = new_grade.id FROM krrg_grades old_grade, krrg_grades new_grade WHERE old_grade.code = 'JUNIOR+' AND new_grade.code = 'JUNIOR_PLUS' AND l.grade_id = old_grade.id AND NOT EXISTS ( SELECT 1 FROM krrg_vacancy_grade_link l2 WHERE l2.vacancy_id = l.vacancy_id AND l2.grade_id = new_grade.id );
-- 2. Удаляем дубликаты ссылок (если после UPDATE появились конфликты) DELETE FROM krrg_vacancy_grade_link l USING krrg_grades old_grade, krrg_grades new_grade WHERE old_grade.code = 'JUNIOR+' AND new_grade.code = 'JUNIOR_PLUS' AND l.grade_id = old_grade.id AND EXISTS ( SELECT 1 FROM krrg_vacancy_grade_link l2 WHERE l2.vacancy_id = l.vacancy_id AND l2.grade_id = new_grade.id );
-- 3. Удаляем запись JUNIOR+ из справочника DELETE FROM krrg_grades WHERE code = 'JUNIOR+';
-- 4. Перепривязываем ссылки с MIDDLE+ на MIDDLE_PLUS UPDATE krrg_vacancy_grade_link l SET grade_id = new_grade.id FROM krrg_grades old_grade, krrg_grades new_grade WHERE old_grade.code = 'MIDDLE+' AND new_grade.code = 'MIDDLE_PLUS' AND l.grade_id = old_grade.id AND NOT EXISTS ( SELECT 1 FROM krrg_vacancy_grade_link l2 WHERE l2.vacancy_id = l.vacancy_id AND l2.grade_id = new_grade.id );
-- 5. Удаляем дубликаты ссылок (если после UPDATE появились конфликты) DELETE FROM krrg_vacancy_grade_link l USING krrg_grades old_grade, krrg_grades new_grade WHERE old_grade.code = 'MIDDLE+' AND new_grade.code = 'MIDDLE_PLUS' AND l.grade_id = old_grade.id AND EXISTS ( SELECT 1 FROM krrg_vacancy_grade_link l2 WHERE l2.vacancy_id = l.vacancy_id AND l2.grade_id = new_grade.id );
-- 6. Удаляем запись MIDDLE+ из справочника DELETE FROM krrg_grades WHERE code = 'MIDDLE+';

rollback.sql:
-- Откат невозможен: старые записи JUNIOR+ и MIDDLE+ удалены,
-- а ссылки перепривязаны. Восстановить исходное состояние нельзя.
SELECT 1;
